with deduped as (select * from (select *, row_number() over (partition by customer_id order by started_at desc, id) as rn from sessions) t where rn = 1) select date_trunc('month', started_at) as activity_month, date_trunc('quarter', started_at) as quarter_start, count_if(browser = 'Edge') as edge_events, sort_array(collect_set(browser)) as browser_list, sort_array(collect_set(browser)) as browser_list_2 from deduped group by date_trunc('month', started_at), date_trunc('quarter', started_at) order by quarter_start desc nulls last;
